('notable_npc', 'hell-lord-rune', 'Full strength punch or kick', '3D6 M.D.', 1, NULL, NULL, 1),
('notable_npc', 'hell-lord-rune', 'Power punch or kick', '6D6 M.D.', 1, NULL, 'Counts as two melee attacks.', 2),
('notable_npc', 'hell-lord-zugard', 'Restrained punch', '1D6x10+31', 0, NULL, 'S.D.C.; Supernatural P.S. 46, as printed.', 0),
('notable_npc', 'hell-lord-zugard', 'Full strength punch, kick or bite', '6D6 M.D.', 1, NULL, 'A bite or blood-drawing claw strike can carry the Death Demon virus.', 1),
('notable_npc', 'hell-lord-zugard', 'Power punch or kick', '2D4x10 M.D.', 1, NULL, 'Counts as two melee attacks.', 2),
('notable_npc', 'hell-lord-zugard', 'Rune pole arm', '1D6x10 M.D.', 1, NULL, 'Giant-sized Rune weapon.', 3),
('notable_npc', 'hell-lord-fury', 'Restrained punch', '1D6 M.D.', 1, NULL, 'Robot P.S. 45, as printed on the Mega-Damage line.', 0),
('notable_npc', 'hell-lord-fury', 'Full strength punch or forward hoof kick', '3D6 M.D.', 1, NULL, NULL, 1),
('notable_npc', 'hell-lord-fury', 'Power punch or rear hoof kick', '1D6x10 M.D.', 1, NULL, 'Counts as two melee attacks.', 2),
('notable_npc', 'hell-lord-fury', 'Kick (Natural Abilities)', '4D6 M.D.', 1, NULL, 'As printed under Natural Abilities for Robotic Strength 45; the Mega-Damage line prints 3D6.', 3),
('notable_npc', 'hell-lord-fury', 'Power kick (Natural Abilities)', '1D4x10+4 M.D.', 1, NULL, 'Counts as two attacks. As printed under Natural Abilities; the Mega-Damage line prints 1D6x10.', 4),
('notable_npc', 'hell-lord-fury', 'Hip energy cannon, single', '5D6 M.D.', 1, '2,000 feet (610 m)', 'Unlimited payload; one melee attack.', 5),
('notable_npc', 'hell-lord-fury', 'Hip energy cannons, both', '1D6x10 M.D.', 1, '2,000 feet (610 m)', 'Both at one target; still one melee attack.', 6),
('notable_npc', 'hell-lord-fury', 'Multi-Optics Eye laser', '3D6 M.D.', 1, '2,000 feet (610 m)', 'Unlimited payload; each blast one attack.', 7),
('notable_npc', 'hell-lord-fury', 'Launched spike', '2D6 M.D.', 1, '300 feet (91.4 m)', 'One at a time, 16 in all, regrowing in 1D4 hours.', 8),
('notable_npc', 'hell-lord-siren', 'Splugorth Fang', '4D6 M.D.', 1, NULL, NULL, 0);
INSERT INTO data_script_runs (filename) VALUES ('~352-megaverse-in-flames-npcs-b.sql');
