-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 notable NPCs are in' AS assertion, count(*) AS got, 4 AS want
  FROM notable_npcs WHERE slug IN ('hell-lord-rune', 'hell-lord-zugard', 'hell-lord-fury', 'hell-lord-siren');
SELECT 'and the notables 17' AS assertion, count(*) AS got, 17 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('hell-lord-rune', 'hell-lord-zugard', 'hell-lord-fury', 'hell-lord-siren');

